{"component": {"id": 28963, "componentId": 15275, "authorUserId": "user_2xmIUPynCyYHPXZPBwS1EDV1Aq8", "name": "Radial Chart", "demoName": "Default", "description": "A radial bar chart for visualizing shares or progress across categories, with full-circle and semi-circle layouts.", "previewUrl": "https://cdn.21st.dev/arihantcodes_1f7b8c4d/radial-chart/default/preview.1790026226341-f4a1ff63-456c-429d-90d1-82f56761ea03.png", "installCommand": "npx shadcn@latest add "https://21st.dev/r/arihantcodes_1f7b8c4d/radial-chart?api_key=$API_KEY_21ST"", "componentCode": ""use client";

import * as React from "react";
import {
  Cell,
  PolarGrid,
  RadialBar,
  RadialBarChart as RechartsRadialBarChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  BROWSER_SHARE,
  CHART_COLORS,
  ChartFrame,
  ChartGlowFilter,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  ChartTooltipContent,
  HOVER_TRANSITION,
  markOpacity,
  useChartId,
  useChartMotion,
} from "@/components/ui/radial-chart-utils/chart-kit";

export type RadialVariant = "full" | "semi";

export interface SpectrumRadialChartProps {
  className?: string;
  data?: typeof BROWSER_SHARE;
  variant?: RadialVariant;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
}

export function RadialChart({
  className,
  data = BROWSER_SHARE,
  variant = "full",
  glowing = false,
  isLoading = false,
  showLegend = true,
}: SpectrumRadialChartProps) {
  const id = useChartId("radial");
  const { isAnimationActive, animationDuration } = useChartMotion();
  const [activeName, setActiveName] = React.useState<string | null>(null);
  const glowId = `${id}-glow`;
  const semi = variant === "semi";
  const rows = data.map((item, index) => ({
    ...item,
    fill: CHART_COLORS[index % CHART_COLORS.length],
  }));

  return (
    <ChartFrame className={cn("flex flex-col", className)}>
      {showLegend ? (
        <ChartLegend
          items={rows.map((item) => ({ label: item.name, color: item.fill }))}
        />
      ) : null}
      {isLoading ? (
        <ChartLoadingBars count={6} />
      ) : (
        <ChartPlotSurface>
          <ResponsiveContainer width="100%" height="100%">
            <RechartsRadialBarChart
              data={rows}
              innerRadius="18%"
              outerRadius="88%"
              startAngle={semi ? 180 : 90}
              endAngle={semi ? 0 : -270}
              cy={semi ? "64%" : "50%"}
              onMouseLeave={() => setActiveName(null)}
            >
              <defs>{glowing ? <ChartGlowFilter id={glowId} /> : null}</defs>
              <PolarGrid
                gridType="circle"
                radialLines={false}
                stroke="currentColor"
                strokeOpacity={0.14}
              />
              <Tooltip content={<ChartTooltipContent />} />
              <RadialBar
                dataKey="value"
                name="Share"
                background={{ fill: "currentColor", fillOpacity: 0.07 }}
                cornerRadius={6}
                isAnimationActive={isAnimationActive}
                animationDuration={animationDuration}
                animationEasing="ease-out"
                filter={glowing ? `url(#${glowId})` : undefined}
              >
                {rows.map((item) => (
                  <Cell
                    key={item.name}
                    fill={item.fill}
                    stroke="var(--spectrum-chart-surface)"
                    strokeWidth={1}
                    style={{
                      opacity: markOpacity(activeName, item.name),
                      transition: HOVER_TRANSITION,
                      cursor: "pointer",
                    }}
                    onMouseEnter={() => setActiveName(item.name)}
                  />
                ))}
              </RadialBar>
            </RechartsRadialBarChart>
          </ResponsiveContainer>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}

export function DefaultRadialChart(props: SpectrumRadialChartProps) {
  return <RadialChart variant="full" {...props} />;
}

export function SemiRadialChart(props: SpectrumRadialChartProps) {
  return <RadialChart variant="semi" {...props} />;
}

export function GlowingRadialChart(props: SpectrumRadialChartProps) {
  return <RadialChart glowing {...props} />;
}

export default RadialChart;
